  +address: string
}

Customer "1" -- "*" Order : places
Customer "1" -- "*" Invoice : receives
Customer "1" -- "*" Warehouse : uses
Order "1" *-- "1..*" OrderLine : contains
OrderLine "*" -- "1" Product : refers to
Order "1" -- "1" Invoice : generates
Order "1" -- "*" Shipment : split into
Shipment "1" *-- "1..*" OrderLine : contains
Shipment "1" -- "0..1" Delivery : results in
Delivery "*" -- "1" Shipment : part of
Warehouse "*" -- "*" Customer : belongs to

@enduml

